package com.hbm.machine.solarboiler;
import net.minecraft.core.*;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.level.material.MapColor;import net.minecraft.world.phys.shapes.*;
/** Actual DecoBlock steel_beam branch: no BE,2pxwide realcollision,retainedplacementmetadata,unchangingverticalOBJ. */
public final class SteelBeamBlock extends Block {
 public static final IntegerProperty META=IntegerProperty.create("legacy_meta",0,15);private static final VoxelShape SHAPE=box(7,0,7,9,16,9);
 public SteelBeamBlock(){super(Properties.of().mapColor(MapColor.METAL).strength(5,9).sound(SoundType.STONE).requiresCorrectToolForDrops().noOcclusion());registerDefaultState(stateDefinition.any().setValue(META,0));}
 @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> builder){builder.add(META);}@Override public BlockState getStateForPlacement(BlockPlaceContext context){return defaultBlockState().setValue(META,context.getHorizontalDirection().get3DDataValue());}@Override protected VoxelShape getShape(BlockState state,BlockGetter level,BlockPos pos,CollisionContext context){return SHAPE;}@Override protected VoxelShape getCollisionShape(BlockState state,BlockGetter level,BlockPos pos,CollisionContext context){return SHAPE;}@Override protected boolean skipRendering(BlockState state,BlockState adjacent,Direction side){return false;}@Override protected int getLightBlock(BlockState state,BlockGetter level,BlockPos pos){return 0;}@Override protected boolean propagatesSkylightDown(BlockState state,BlockGetter level,BlockPos pos){return true;}
 @Override protected BlockState rotate(BlockState state,Rotation rotation){int meta=state.getValue(META);return meta>=2&&meta<=5?state.setValue(META,rotation.rotate(Direction.from3DDataValue(meta)).get3DDataValue()):state;}@Override protected BlockState mirror(BlockState state,Mirror mirror){int meta=state.getValue(META);return meta>=2&&meta<=5?rotate(state,mirror.getRotation(Direction.from3DDataValue(meta))):state;}
}
